//! r14_p1: a ploughed field rising to a crest on an October morning, the
//! towers of a small Baltic town standing out of the mist in the lowland
//! beyond, a cart track running over the rise toward them.
//!
//!   cargo paint r14_p1 -- --full --width 2400
//!   cargo paint r14_p1 -- --full --width 2400 --crop x0,y0,x1,y1

use paint::atmos::{Cloud, Clouds, Sky, SkyField};
use paint::color::{Mix, mix};
use paint::scene::{Sun, World};
use paint::{Fbm, Handling, Mask, Rgb, Rng, Shape, Stipple, Style, Tool, hex, smoothstep};
use paintings::run::{Finish, Run};

const ASPECT: f32 = 1.4;
const H: f32 = 1000.0 / ASPECT;
/// Eye level on the canvas.
const HZ: f32 = 452.0;
const EYE: f32 = 1.6;
/// The furrows' heading on the ground (radians from straight ahead, + to
/// the right): away and to the left.
const PHI: f32 = -0.62;
/// Ridge to ridge (m).
const FURROW: f32 = 0.36;

/// Where the rise crests (m away) and how high (m), along X.
fn crest_z(x: f32) -> f32 {
    62.0 + 9.0 * (x * 0.021 + 0.7).sin() + 4.0 * (x * 0.067 + 2.0).sin()
}
fn crest_h(x: f32) -> f32 {
    0.55 + 0.16 * (x * 0.017 + 1.3).sin() + 0.06 * (x * 0.05).sin()
}
/// The ground: rising from the painter's feet to a rounded crest, then
/// falling away to the flat lowland 17 m below.
fn ground(x: f32, z: f32) -> f32 {
    let (zc, hc) = (crest_z(x), crest_h(x));
    let lumps = 0.05 * (x * 0.31 + 1.0).sin() * (z * 0.23).sin() + 0.03 * (x * 0.9).sin() * (z * 0.7 + 2.0).sin();
    if z <= zc {
        let t = (z / zc).clamp(0.0, 1.0);
        hc * (1.0 - (1.0 - t) * (1.0 - t)) + lumps * t
    } else {
        let s = ((z - zc) / 340.0).clamp(0.0, 1.0);
        hc - 17.0 * s * s * (3.0 - 2.0 * s)
    }
}

fn world() -> World {
    World::new([0.0, 0.0, 1000.0, H], HZ, EYE).fov(1000.0, 45.0).ground(ground).sun(Sun::deg(-64.0, 5.5)).visibility(9000.0)
}

/// The top of the field on the canvas (its crest seen against what lies
/// beyond), per column.
fn crest_y(w: &World, x: f32) -> f32 {
    let mut best = f32::MAX;
    let mut z = 4.0;
    while z < 420.0 {
        let wx = (x - w.cx) * z / w.focal;
        let y = HZ + w.focal * (EYE - ground(wx, z)) / z;
        best = best.min(y);
        z += 0.25 + z * 0.004;
    }
    best
}

/// The far country's skyline above the horizon: open flat land with low
/// woods in unequal stretches (units above HZ).
fn far_rise(x: f32, n: &Fbm) -> f32 {
    let woods = [(40.0, 150.0, 3.2), (205.0, 262.0, 2.2), (300.0, 360.0, 4.0), (820.0, 905.0, 2.6), (930.0, 1000.0, 3.6)];
    let mut r: f32 = 0.6 + 0.4 * n.get(x * 0.2, 0.0);
    for (a, b, h) in woods {
        let k = smoothstep(a, a + 12.0, x) * (1.0 - smoothstep(b - 10.0, b, x));
        let crown = h * (0.75 + 0.35 * n.get01(x * 1.7, 3.0) + 0.25 * n.get(x * 5.0, 7.0));
        r = r.max(k * crown);
    }
    r
}

/// The furrows at a ground point: (across-coordinate phase 0..1, the
/// local heading on the ground).
fn furrow(x: f32, z: f32) -> (f32, f32) {
    // the plough bends a little over the rise
    let bend = 2.2 * (z * 0.045 + 0.4).sin() + 0.8 * (x * 0.03).sin();
    let head = PHI + 0.1 * (z * 0.045 + 0.4).cos();
    let u = x * PHI.cos() - z * PHI.sin() + bend;
    ((u / FURROW).rem_euclid(1.0), head)
}

fn main() {
    let o = Run::new("r14_p1");
    let st = Style::friedrich();
    let pal = &st.palette;
    let mut rng = Rng::new(o.seed);
    let mut c = o.canvas(|| st.prepare(o.width, ASPECT, o.seed));
    let f = c.frame();
    let w = world();
    let w = &w;
    let sun = w.sun;

    // ---------------------------------------------------------------- air
    let sky = Sky::new(sun).haze(3.0).uneven(0.5, 25_000.0, 11).layer(700.0, 400.0, 1.4, 0.7, 5);
    let sf = SkyField::new(sky, w, 6.0);
    let bal = sf.sky.sunlight();
    let sf = sf.balance(bal, 0.35).exposure(1.02);
    let clouds = Clouds::new(vec![
        // a high thin deck in long level streaks, thinning toward the zenith
        Cloud::stratus(5_500.0, 600.0, 0.42, 12).density(0.004).soft(0.55).wind(0.15, 7.0).reach(3_000.0, 60_000.0),
        // a low grey bank lying over the far country on the right
        Cloud::bank(2_000.0, 30_000.0, 26_000.0, 8_000.0, 500.0, 1_700.0, 4).density(0.02),
    ]);
    let cf = clouds.field(&sf, w, 3.0);
    let (sf, cf) = (&sf, &cf);
    let nfar = Fbm::new(o.seed as u32 + 3, 4, 60.0);
    let crest = f.per_column(move |x| crest_y(w, x));
    let far_top = f.per_column(move |x| HZ - far_rise(x, &nfar));
    let band = Fbm::new(o.seed as u32 + 17, 3, 1.0);

    if std::env::args().any(|a| a == "--probe") {
        for y in [20.0, 120.0, 250.0, 350.0, 420.0, 448.0] {
            let row: Vec<String> = [30.0, 250.0, 500.0, 750.0, 970.0].iter().map(|&x| {
                let p = cf.color(sf, x, y);
                format!("{:02x}{:02x}{:02x}", (paint::color::linear_to_srgb(p[0]) * 255.0) as u8, (paint::color::linear_to_srgb(p[1]) * 255.0) as u8, (paint::color::linear_to_srgb(p[2]) * 255.0) as u8)
            }).collect();
            eprintln!("y {y:>5}: {}", row.join(" "));
        }
        let cs: Vec<i32> = (0..11).map(|i| crest(i as f32 * 99.9 + 0.05) as i32).collect();
        eprintln!("crest {cs:?}");
        return;
    }

    // the sky's color as the painter mixes it: the field, with the slow
    // unequal banding of a morning sky laid in horizontal strokes
    let sky_col = move |x: f32, y: f32| -> Rgb {
        let y = y.min(HZ - 0.5);
        let base = cf.color(sf, x, y);
        let b = band.get(x * 0.0022, y * 0.018);
        let k = 1.0 + 0.035 * b;
        [base[0] * k, base[1] * k, base[2] * k]
    };

    // ---------------------------------------------------------------- sky
    let sky_m = Mask::from_fn(f, move |x, y| if y < HZ + 6.0 { 1.0 } else { 0.0 });
    if o.stage("sky", &mut c, &mut rng) {
        let hd = st.broad().color(sky_col).angle(|_, _| 0.0).angle_jitter(0.06).length(60.0, 200.0).coverage(3.4).medium(0.4).clip(true).threshold(0.3);
        c.work(&sky_m, &hd, 11);
        if let Some(b) = st.blend() {
            c.work(&sky_m, &b.clip(true).angle(|_, _| 0.0).angle_jitter(0.1), 12);
        }
        // stippled into the wet, the same color from the field beneath
        let sp = Stipple::new(Tool::stippler(2.6)).mixed(pal, 0.45).color(sky_col).coverage(|_, _| 1.3).pressure(0.4, 0.75).dips(18, 0.4, 0.5).cluster(0.35, None).clip(true);
        c.stipple(&sky_m, &sp, 13);
        c.wait(90.0);
        // the cloud streaks, laid level into the still-open sky
        let body = cf.mask(f, |p| smoothstep(0.12, 0.6, p.alpha)).mul(&sky_m);
        let hd = st.body().color(sky_col).angle(|_, _| 0.0).angle_jitter(0.08).length(20.0, 70.0).coverage(2.2).pressure(0.45, 0.75).medium(0.35).clip(true).threshold(0.25);
        c.work(&body, &hd, 14);
        if let Some(b) = st.blend() {
            let soft = cf.mask(f, |p| smoothstep(0.03, 0.2, p.alpha)).mul(&sky_m);
            c.work(&soft, &b.clip(true).angle(|_, _| 0.0).angle_jitter(0.1).length(40.0, 120.0).pressure(0.3, 0.4), 15);
        }
        c.dry();
        // dry: a finer stipple barely off the field, denser toward the glow
        let sp = Stipple::new(Tool::stippler(1.7)).mixed(pal, 0.5).color(sky_col).coverage(move |x, y| 0.7 + 0.6 * smoothstep(250.0, 440.0, y) * (1.0 - smoothstep(0.0, 700.0, x))).pressure(0.35, 0.7).dips(16, 0.35, 0.6).cluster(0.4, None).clip(true);
        c.stipple(&sky_m, &sp, 16);
        c.dry();
    }

    // ------------------------------------------------ the far country
    let far_m = Mask::from_fn(f, move |x, y| if y >= far_top(x) && y < crest(x) + 3.0 { 1.0 } else { 0.0 });
    if o.stage("far", &mut c, &mut rng) {
        // the far land: a cool grey-violet lowland, woods a step darker,
        // the whole lost toward the horizon in the air
        let land = move |x: f32, y: f32| -> Rgb {
            let air = sf.airlight(x);
            let woods = smoothstep(0.8, 2.0, HZ - far_top(x)) * smoothstep(far_top(x) - 0.5, far_top(x) + 2.5, y);
            let base = mix(hex("#6d6f6b"), hex("#3f4549"), woods, Mix::Pigment);
            // nearer (lower) is less veiled
            let d = ((y - HZ) / (crest(x) - HZ).max(1.0)).clamp(0.0, 1.0);
            mix(base, air, 0.72 - 0.25 * d, Mix::Light)
        };
        let hd = st.body().color(land).angle(|_, _| 0.0).angle_jitter(0.04).length(15.0, 45.0).coverage(3.0).pressure(0.5, 0.75).clip(true).threshold(0.3);
        c.work(&far_m, &hd, 21);
        c.dry();
    }

    // ---------------------------------------------------------- the field
    let field_m = Mask::from_fn(f, move |x, y| if y >= crest(x) - 0.3 { 1.0 } else { 0.0 });
    let clods = Fbm::new(o.seed as u32 + 31, 4, 1.0);
    // the earth's color at a canvas point: faces of the turned slices lit
    // by the low sun from ahead-left, the others in the cool of the sky
    let earth = move |x: f32, y: f32| -> Rgb {
        let Some(p) = w.to_ground(x, y.max(crest(x) + 0.3)) else { return hex("#4a4038") };
        let (gx, gz) = (p[0], p[2]);
        let (ph, _) = furrow(gx, gz);
        // the slice: a gentle rise to the ridge, a steep fall to the trough
        let lit = if ph < 0.62 { smoothstep(0.0, 0.25, ph) * (1.0 - smoothstep(0.5, 0.62, ph)) } else { 0.0 };
        let trough = smoothstep(0.62, 0.8, ph) * (1.0 - smoothstep(0.92, 1.0, ph));
        // how finely the furrows are seen: fade the pattern where they
        // come closer together than a small brush can say
        let px = FURROW * w.scale_at(gz);
        let seen = smoothstep(2.5, 9.0, px);
        let lit = 0.4 + (lit - 0.4) * seen;
        let trough = 0.25 + (trough - 0.25) * seen;
        let shade = hex("#3b322b");
        let sunlit = hex("#8a6a4c");
        let skylit = hex("#6b625c");
        let c0 = mix(shade, sunlit, lit, Mix::Pigment);
        let c0 = mix(c0, skylit, 0.25 * (1.0 - lit), Mix::Pigment);
        let c0 = mix(c0, hex("#221c19"), 0.55 * trough, Mix::Pigment);
        let n = clods.get(gx * 1.3, gz * 1.3);
        let c0 = mix(c0, hex("#5d4a3a"), 0.25 * n.max(0.0), Mix::Pigment);
        mix(c0, sf.airlight(x), w.aerial(gz) + 0.18 * smoothstep(25.0, 70.0, gz), Mix::Light)
    };
    let along = move |x: f32, y: f32| -> f32 {
        let Some(p) = w.to_ground(x, y.max(crest(x) + 0.3)) else { return 0.0 };
        let (_, head) = furrow(p[0], p[2]);
        let (dx, dz) = (head.sin() * 0.5, head.cos() * 0.5);
        let a = w.project([p[0], ground(p[0], p[2]), p[2]]).unwrap_or((x, y));
        let b = w.project([p[0] + dx, ground(p[0] + dx, p[2] + dz), p[2] + dz]).unwrap_or((x + 1.0, y));
        (b.1 - a.1).atan2(b.0 - a.0)
    };
    // depth bands, each with the brush its furrows want
    let zmap = Mask::from_fn(f, move |x, y| if y >= crest(x) - 0.3 { w.to_ground(x, y.max(crest(x) + 0.3)).map_or(80.0, |p| p[2]) } else { 1e4 });
    if o.stage("field", &mut c, &mut rng) {
        let bands: [(f32, f32, f32); 4] = [(0.0, 13.0, 8.0), (11.0, 24.0, 4.8), (21.0, 42.0, 2.8), (38.0, 1e3, 1.9)];
        for (i, &(z0, z1, wd)) in bands.iter().enumerate() {
            let m = zmap.clone().map(move |z| if z >= z0 && z < z1 { 1.0 } else { 0.0 }).mul(&field_m);
            let tool = Tool { lay: 0.75, ..Tool::filbert(wd) };
            let hd = Handling::new(tool).mixed(pal, 0.18).mix_jitter(0.07).color(earth).angle(along).angle_jitter(0.07).length(wd * 3.0, wd * 9.0).coverage(3.0).pressure(0.6, 0.9).curve(0.03, 0.2).tail(0.15).broken(0.1).swell(0.2).dips(2, 0.6, 0.6).clip(true).threshold(0.2);
            c.work(&m, &hd, 40 + i as u64);
        }
        c.dry();
    }

    let _ = (Shape::new(),);
    o.finish(&mut c, &mut rng, &Finish::aged(st.relief));
}

