        v = v.max(a);
    }
    v
}

/// A crow on the ground at a canvas point, `s` units per meter, facing
/// left or right, head down or up.
fn crow(c: &mut Canvas, pal: &Palette, at: (f32, f32), s: f32, facing: f32, pecking: bool, seed: u64) {
    let mut r = Rng::new(seed);
    let p = |u: f32, v: f32| (at.0 + facing * u * s, at.1 - v * s);
    let black = pal.paint(hex("#18181c"), 0.12);
    let sheen = pal.paint(hex("#44464f"), 0.12);
    let mut b = Held::new(Tool::round_sable((0.075 * s).max(0.5)), seed);
    let tilt = if pecking { -0.06 } else { 0.05 };
    // the body: tail to breast, three pulls
    for (dv, pr) in [(0.0f32, 0.85f32), (0.035, 0.7), (-0.03, 0.6)] {
        b.reload(black, 1.0);
        let g = Gesture::new(vec![p(-0.24, 0.13 + dv + r.range(-0.005, 0.005)), p(-0.05, 0.14 + dv + tilt * 0.5), p(0.12, 0.13 + dv + tilt)]).pressure(pr * 0.6, pr);
        c.drag(&mut b, &g, None);
    }
    // head and beak
    let (hx, hy) = if pecking { (0.2, 0.06) } else { (0.17, 0.23) };
    b.reload(black, 1.0);
    c.drag(&mut b, &Gesture::new(vec![p(0.1, 0.15 + tilt), p(hx - 0.02, hy + 0.01)]).pressure(0.75, 0.8), None);
    let mut t = Held::new(Tool::round_sable((0.035 * s).max(0.4)), seed + 1);
    t.reload(black, 1.0);
    let (bx, by) = if pecking { (hx + 0.05, hy - 0.06) } else { (hx + 0.09, hy - 0.02) };
    c.drag(&mut t, &Gesture::new(vec![p(hx, hy), p(bx, by)]).pressure(0.7, 0.2), None);
    // legs
    for lx in [-0.02f32, 0.04] {
        t.reload(black, 0.8);
        c.drag(&mut t, &Gesture::new(vec![p(lx, 0.09), p(lx + 0.01, 0.0)]).pressure(0.5, 0.35), None);
    }
    // the sky's light along the back
    let mut sh = Held::new(Tool::round_sable((0.025 * s).max(0.4)), seed + 2);
    sh.reload(sheen, 0.8);
    c.drag(&mut sh, &Gesture::new(vec![p(-0.16, 0.19), p(0.02, 0.2 + tilt * 0.5)]).pressure(0.3, 0.5), None);
}

