//! r14_p1 probe
use paint::atmos::{Ranges, Sky, SkyField, Haze};
use paint::scene::{Sun, World};
use paint::{Style};

const ASPECT: f32 = 1.42;
const H: f32 = 1000.0 / ASPECT;
const HORIZON: f32 = 318.0;
const EYE: f32 = 1150.0;

fn world() -> World {
    World::new([0.0, 0.0, 1000.0, H], HORIZON, EYE).fov(1000.0, 48.0).sun(Sun::deg(-14.0, -2.2)).visibility(60_000.0)
}

fn hexs(c: [f32; 3]) -> String {
    let s = |v: f32| (v.clamp(0.0, 1.0).powf(1.0 / 2.2) * 255.0) as u8;
    format!("#{:02x}{:02x}{:02x}", s(c[0]), s(c[1]), s(c[2]))
}

fn main() {
    let _st = Style::friedrich();
    let w = world();
    let sky = Sky::new(w.sun).haze(2.4).uneven(0.5, 30_000.0, 11);
    let sf = SkyField::new(sky, &w, 6.0);
    for y in [0.0f32, 60.0, 120.0, 180.0, 240.0, 280.0, 300.0, 312.0] {
        let row: Vec<String> = [0.0f32, 200.0, 330.0, 400.0, 500.0, 700.0, 1000.0].iter().map(|&x| hexs(sf.at(x, y))).collect();
        eprintln!("y {y:5}: {}", row.join(" "));
    }
    eprintln!("focal {}", w.focal);
    let air = Haze::new(60_000.0).height(1000.0).mist(700.0, 5.0, 120.0, 7);
    for l in Ranges::new(5_000.0, 90_000.0, 6, 17).heights(1000.0, 1500.0).build(&w) {
        let ys: Vec<i32> = (0..11).map(|i| l.crest(&w, i as f32 * 100.0) as i32).collect();
        eprintln!("k {} z {:.0} crest {:?} haze@crest {:.2}", l.k, l.z, ys, l.haze(&w, &air, 500.0, l.crest(&w, 500.0)));
    }
}
