//! r14_p1: "Morning in the Mountains" — an original landscape in the manner
//! of Caspar David Friedrich (see notes/r14_p1.md).
//!
//! From a granite summit before sunrise: the glow low on the left over
//! ranges that step back in value to the horizon, a sea of mist filling the
//! valleys between them, two dark wooded ridges rising out of it, and on
//! the near summit, among heath and boulders, a group of spruces standing
//! against the mist on the right.
//!
//!   cargo paint r14_p1 -- --full --width 2400
//!   cargo paint r14_p1 -- --full --width 2400 --crop x0,y0,x1,y1
//!   cargo paint r14_p1 -- --full --width 2400 --ckpt / --resume <stage>

use paint::color::{Mix, mix};
use paint::{Apply, Fbm, Form, Gesture, Ground, Held, Light, Mask, Palette, Rgb, Sdf, Stipple, Style, Tool, gradient, hex, smoothstep};
use paintings::run::{Finish, Run};
use std::f32::consts::PI;

const ASPECT: f32 = 1.42;
const H: f32 = 1000.0 / ASPECT;
/// The eye's level: the farthest ranges sink to it.
const HORIZON: f32 = 322.0;
/// Where the sun will come up (canvas x).
const GLOW_X: f32 = 300.0;

// ------------------------------------------------------------- the sky

fn sky_col(bands: &Fbm, x: f32, y: f32) -> Rgb {
    // height above the horizon as a fraction of the sky, wandered a little
    // by unequal horizontal bands (a hand doesn't lay a formula)
    let t0 = ((HORIZON - y) / HORIZON).clamp(0.0, 1.0);
    let t = (t0 + 0.035 * bands.get(x * 0.35, y * 4.0) * smoothstep(0.02, 0.2, t0)).clamp(0.0, 1.0);
    let base = gradient(
        &[
            (0.00, hex("#dca77e")),
            (0.035, hex("#e6bf90")),
            (0.09, hex("#e8d0a4")),
            (0.20, hex("#dcd5bb")),
            (0.36, hex("#c3c6c1")),
            (0.58, hex("#a2adbd")),
            (1.00, hex("#7a8cab")),
        ],
        t,
        Mix::Light,
    );
    let dx = (x - GLOW_X) / 330.0;
    let g = (-(dx * dx)).exp();
    // the glow over the sun's place: warm, falling off faster upward
    let glow = g * (-t / 0.16).exp();
    let c = mix(base, hex("#f0cc92"), 0.55 * glow, Mix::Light);
    // away from the glow, the low sky goes rose-lilac
    let away = (1.0 - g) * (-t / 0.12).exp();
    mix(c, hex("#c6a9a6"), 0.55 * away, Mix::Light)
}

/// Cloud streaks lying in the upper sky, level and thin: (alpha, under)
/// where `under` is 1 on the side that faces the glow (below).
fn streaks(n: &Fbm, x: f32, y: f32) -> (f32, f32) {
    // (center y, x0, x1, thickness, tilt)
    let list: [(f32, f32, f32, f32, f32); 6] = [
        (62.0, 430.0, 1060.0, 9.0, -0.02),
        (92.0, 560.0, 980.0, 6.0, -0.015),
        (128.0, -40.0, 380.0, 7.0, 0.02),
        (150.0, 620.0, 1040.0, 11.0, -0.01),
        (205.0, 740.0, 1050.0, 7.0, 0.0),
        (262.0, -30.0, 240.0, 5.0, 0.01),
    ];
    let mut a: f32 = 0.0;
    let mut under: f32 = 0.0;
    for (k, &(yc, x0, x1, th, tilt)) in list.iter().enumerate() {
        let yc = yc + tilt * (x - x0) + 6.0 * n.get(x * 0.4, k as f32 * 7.0);
        let env = smoothstep(x0, x0 + 120.0, x) * (1.0 - smoothstep(x1 - 150.0, x1, x));
        let th = th * (0.6 + 0.8 * n.get01(x * 0.8, k as f32 * 3.0 + 1.0));
        let d = (y - yc) / th;
        let v = (-(d * d)).exp() * env * smoothstep(0.25, 0.65, n.get01(x * 1.6, y * 0.6 + k as f32 * 5.0));
        if v > a {
            a = v;
            under = smoothstep(-0.3, 0.9, d);
        }
    }
    (a.min(1.0), under)
}

fn sky_with_clouds(bands: &Fbm, cn: &Fbm, x: f32, y: f32) -> Rgb {
    let s = sky_col(bands, x, y);
    let (a, under) = streaks(cn, x, y);
    if a <= 0.0 {
        return s;
    }
    // the bodies are a violet-gray darker than the sky round them; their
    // undersides take the glow
    let t = ((HORIZON - y) / HORIZON).clamp(0.0, 1.0);
    let body = mix(hex("#8f8c9e"), hex("#a69aa4"), smoothstep(0.3, 0.8, 1.0 - t), Mix::Light);
    let warm = mix(hex("#d7ad9a"), hex("#e2bd95"), smoothstep(0.3, 0.8, 1.0 - t), Mix::Light);
    let cl = mix(body, warm, under * 0.8, Mix::Light);
    mix(s, cl, 0.75 * a, Mix::Light)
}

// ---------------------------------------------------------- the ranges

/// The far ranges, far to near: crest y at canvas x.
fn far1(n: &Fbm, x: f32) -> f32 {
    // the farthest: a long low line just under the horizon glow
    HORIZON + 6.0 - 7.0 * smoothstep(520.0, 760.0, x) * (1.0 - smoothstep(820.0, 990.0, x)) - 3.0 * n.get01(x * 1.5, 0.3) - 5.0 * (-((x - 120.0) / 70.0).powi(2)).exp()
}
fn far2(n: &Fbm, x: f32) -> f32 {
    // a broad massif on the left with a rounded summit, falling to the right
    let dome = 34.0 * (1.0 - ((x - 170.0) / 230.0).powi(2)).max(0.0).powf(0.8);
    let shoulder = 16.0 * (1.0 - ((x - 420.0) / 140.0).powi(2)).max(0.0);
    HORIZON + 22.0 - dome - shoulder + 3.0 * n.get(x * 2.0, 1.1) + 1.5 * n.get(x * 9.0, 2.0) + 10.0 * smoothstep(450.0, 700.0, x)
}
fn far3(n: &Fbm, x: f32) -> f32 {
    // a jagged range coming in from the right, ending at a cliff on its left
    let peak = 30.0 * (1.0 - ((x - 820.0) / 150.0).abs()).max(0.0).powf(1.3);
    let body = 26.0 * smoothstep(540.0, 610.0, x);
    HORIZON + 62.0 - body - peak + 4.0 * n.get(x * 2.5, 3.3) + 2.0 * n.get(x * 11.0, 4.0)
}
/// The mountain's foot in each range: where the mist takes it.
const FOOT1: f32 = HORIZON + 14.0;

// ---------------------------------------------------- the near country

/// The two wooded ridges rising out of the mist: crest y at canvas x
/// (above the ridge; `None`-like big value where there is no ridge).
fn ridge_l(n: &Fbm, x: f32) -> f32 {
    let base = 392.0 + 0.11 * x + 55.0 * smoothstep(250.0, 470.0, x);
    base + 5.0 * n.get(x * 1.7, 5.0) + firs_edge(x, 3.1, 7.0)
}
fn ridge_r(n: &Fbm, x: f32) -> f32 {
    let base = 470.0 - 45.0 * smoothstep(520.0, 760.0, x) - 12.0 * smoothstep(800.0, 1000.0, x);
    base + 4.0 * n.get(x * 1.9, 6.0) + firs_edge(x, 2.4, 5.5)
}
/// A serrated line of small fir tops along a crest (negative = up).
fn firs_edge(x: f32, spacing: f32, h: f32) -> f32 {
    let k = (x / spacing).floor();
    let u = x / spacing - k;
    let r = |i: f32| ((i * 12.9898).sin() * 43758.545).fract().abs();
    let hk = h * (0.35 + 0.65 * r(k)) * if r(k + 0.5) < 0.2 { 0.2 } else { 1.0 };
    -hk * (1.0 - (2.0 * u - 1.0).abs()).powf(1.3)
}

/// The near summit's edge: y at canvas x.
fn fg_top(n: &Fbm, x: f32) -> f32 {
    let slope = 612.0 - 0.13 * x - 38.0 * smoothstep(600.0, 820.0, x);
    let knoll = 30.0 * (-((x - 150.0) / 110.0).powi(2)).exp();
    slope - knoll + 5.0 * n.get(x * 1.3, 8.0) + 2.0 * n.get(x * 6.0, 9.0)
}

// ------------------------------------------------------------- helpers

fn fam<'a>(pal: &Palette, names: &[&str]) -> Palette {
    pal.only(names)
}

/// A spruce written with the brush: its dark body first (short strokes
/// down and out along drooping tiers), then the branch ends pulled out
/// past the silhouette, then a few touches of sky light on the side toward
/// the glow, then the leader.
#[allow(clippy::too_many_arguments)]
fn spruce(c: &mut paint::Canvas, st: &Style, pal: &Palette, x0: f32, base: f32, hgt: f32, lean: f32, dark: Rgb, lit: Rgb, seed: u64) {
    let f = c.frame();
    let mut rng = paint::Rng::new(seed);
    let r = |i: i32, j: i32| ((((i as f32) * 12.9898 + (j as f32) * 78.233 + seed as f32 * 0.137).sin()) * 43758.545).fract().abs();
    let tiers = (hgt / 15.0).round().max(6.0);
    // trunk line leaning a little
    let cx = move |v: f32| x0 + lean * hgt * v;
    let half = move |v: f32, side: f32| {
        if !(0.0..=1.0).contains(&v) {
            return 0.0;
        }
        let taper = 0.21 * hgt * (1.0 - v).powf(0.92);
        let tv = v * tiers + 0.37 * r(7, 0);
        let k = tv.floor() as i32;
        let s = tv - tv.floor();
        // each tier widest at its drooping ends (bottom), narrow at its top
        let droop = 0.55 + 0.45 * (1.0 - s).powf(1.6);
        let own = 0.7 + 0.5 * r(k, if side < 0.0 { 1 } else { 2 });
        // the lowest boughs thin out toward the ground
        let low = 0.75 + 0.25 * smoothstep(0.0, 0.12, v);
        taper * droop * own * low
    };
    let sil = Mask::from_fn(f, move |x, y| {
        let v = (base - y) / hgt;
        if !(0.0..=1.0).contains(&v) {
            return 0.0;
        }
        let dx = x - cx(v);
        let w = half(v, dx.signum());
        smoothstep(w + 0.6, w - 0.6, dx.abs())
    })
    .roughen(seed as u32, 3.0, 1.2, 0.5);
    // 1. the dark body, short strokes down and out along the boughs
    let hd = st
        .hatch()
        .palette(pal)
        .color(move |x, y| {
            let v = ((base - y) / hgt).clamp(0.0, 1.0);
            let side = (x - cx(v)).signum();
            // the side toward the glow a touch cooler and lighter
            mix(dark, lit, if side < 0.0 { 0.12 } else { 0.0 } + 0.05 * v, Mix::Pigment)
        })
        .angle(move |x, y| {
            let v = ((base - y) / hgt).clamp(0.0, 1.0);
            if x > cx(v) { 0.45 } else { PI - 0.45 }
        })
        .angle_jitter(0.25)
        .length(3.0, 8.0)
        .coverage(3.2)
        .clip(true)
        .threshold(0.3);
    c.work(&sil, &hd, seed + 1);
    // 2. bough ends pulled out and down past the silhouette
    let tool = Tool { point: 0.8, ..Tool::round_sable(1.3) };
    let mut held = Held::new(tool.clone(), seed + 2);
    let dark_p = pal.paint(dark, 0.15);
    held.load(dark_p, 0.8);
    let nt = tiers as i32;
    for k in 0..nt {
        let v = (k as f32 + 0.37 * r(7, 0)) / tiers;
        if v > 0.9 {
            continue;
        }
        for side in [-1.0f32, 1.0] {
            let w = half(v + 0.001, side);
            if w < 1.5 {
                continue;
            }
            let yb = base - v * hgt;
            let xs = cx(v) + side * w * 0.3;
            let reach = w * (0.95 + 0.3 * r(k, 11 + side as i32));
            let drop = (0.25 + 0.2 * r(k, 13)) * reach;
            let pts: Vec<(f32, f32)> = (0..6)
                .map(|i| {
                    let t = i as f32 / 5.0;
                    let x = xs + side * (reach - w * 0.3) * t;
                    // droop, then the tip turns up a little
                    let y = yb - 1.5 + drop * (t * t) - 0.2 * drop * smoothstep(0.8, 1.0, t);
                    (x + rng.normal() * 0.3, y + rng.normal() * 0.3)
                })
                .collect();
            if held.fullness() < 0.35 {
                held.reload(dark_p, 0.8);
            }
            c.drag(&mut held, &Gesture::new(pts).pressure(0.75, 0.25).ramps(0.05, 0.4), None);
        }
    }
    // 3. sky light on the upper sides of the boughs toward the glow
    let lit_p = pal.paint(lit, 0.2);
    let mut lh = Held::new(Tool { point: 0.8, ..Tool::round_sable(1.0) }, seed + 3);
    lh.load(lit_p, 0.6);
    for k in 0..nt {
        let v = (k as f32 + 0.37 * r(7, 0)) / tiers;
        if v > 0.93 || r(k, 21) < 0.3 {
            continue;
        }
        let w = half(v + 0.001, -1.0);
        let yb = base - v * hgt;
        let n = 2 + (r(k, 22) * 3.0) as i32;
        for j in 0..n {
            let t0 = 0.35 + 0.55 * r(k, 30 + j);
            let x = cx(v) - w * t0;
            let y = yb - 2.0 + 0.3 * w * t0 * t0 - 1.5 * r(k, 40 + j);
            let len = 1.5 + 2.5 * r(k, 50 + j);
            if lh.fullness() < 0.3 {
                lh.reload(lit_p, 0.6);
            }
            c.drag(&mut lh, &Gesture::new(vec![(x + len * 0.6, y - 0.4 * len), (x - len * 0.4, y + 0.3 * len)]).pressure(0.5, 0.2).ramps(0.1, 0.5), None);
        }
    }
    // 4. the leader: a fine line to the tip, a little crooked
    let mut rh = Held::new(Tool { point: 1.0, ..Tool::rigger(0.7) }, seed + 4);
    rh.load(dark_p, 0.6);
    let top = base - hgt;
    let pts = vec![(cx(0.86), base - 0.86 * hgt), (cx(0.93) + 0.3, base - 0.93 * hgt), (cx(1.0) - 0.2, top - 2.0)];
    c.drag(&mut rh, &Gesture::new(pts).pressure(0.7, 0.1).ramps(0.05, 0.5), None);
}

// ---------------------------------------------------------------- main

fn main() {
    let o = Run::new("r14_p1");
    let mut st = Style::friedrich();
    // a Dresden ground: warm lower layers, then a patchy whitish top of lead
    // white in oil [KÖR p.284], so the pale sky keeps its coolness
    st.ground.push(Ground { color: hex("#d4c9b4"), hiding: 0.6, um: 30.0, stiff: 0.4, apply: Apply::Brush });
    let greens = Palette::friedrich_1820_greens();
    let mut rng = paint::Rng::new(o.seed);
    let mut c = o.canvas(|| st.prepare(o.width, ASPECT, o.seed));
    let f = c.frame();

    let bands = Fbm::new(11, 4, 260.0);
    let cn = Fbm::new(12, 4, 120.0);
    let rn = Fbm::new(13, 4, 90.0);

    let sky_pal = fam(&st.palette, &["lead white", "cobalt blue", "pale smalt", "yellow ochre", "vermilion", "chrome yellow", "raw umber"]);
    let top1 = f.per_column(move |x| far1(&rn, x));
    let sky = Mask::from_fn(f, move |x, y| if y < top1(x) + 3.0 { 1.0 } else { 0.0 });

    if o.stage("sky", &mut c, &mut rng) {
        let col = move |x: f32, y: f32| sky_with_clouds(&bands, &cn, x, y.min(HORIZON + 2.0));
        // lay-in: long, nearly level strokes of thin paint, the clouds laid
        // in with it so they sit in the wet sky
        let hd = st.broad().palette(&sky_pal).color(col).angle(|_, _| 0.0).angle_jitter(0.04).length(60.0, 180.0).coverage(4.0).clip(true).threshold(0.3);
        c.work(&sky, &hd, 101);
        // the streaks again, in smaller strokes along them, still wet
        let cl = Mask::from_fn(f, move |x, y| smoothstep(0.15, 0.5, streaks(&cn, x, y).0));
        let hd = st.body().palette(&sky_pal).color(col).angle(|_, _| 0.0).angle_jitter(0.05).length(20.0, 70.0).coverage(2.0).pressure(0.4, 0.6).clip(true).threshold(0.2);
        c.work(&cl, &hd, 102);
        if let Some(b) = st.blend() {
            c.work(&sky, &b.angle(|_, _| 0.0), 103);
        }
        // stipple into the wet paint: breaks the strokes, keeps the tones
        let sp = Stipple::new(Tool::stippler(2.6)).mixed(&sky_pal, 0.45).color(col).coverage(|_, _| 1.4).pressure(0.45, 0.8).dips(18, 0.4, 0.5).cluster(0.3, None).clip(true);
        c.stipple(&sky, &sp, 104);
        c.dry();
        // dry: a finer stipple barely lighter than the field, denser toward the glow
        let sp = Stipple::new(Tool::stippler(1.6))
            .mixed(&sky_pal, 0.5)
            .color_over(|_, _, u| paint::shift(u, 0.018, 0.0, 0.004))
            .coverage(move |x, y| {
                let dx = (x - GLOW_X) / 380.0;
                1.8 * smoothstep(40.0, HORIZON, y) * (0.35 + 0.65 * (-(dx * dx)).exp())
            })
            .pressure(0.4, 0.75)
            .dips(22, 0.35, 0.6)
            .clip(true);
        c.stipple(&sky, &sp, 105);
        c.dry();
    }

    // ------------------------------------------------ the far ranges
    let far_pal = fam(&st.palette, &["lead white", "cobalt blue", "pale smalt", "red earth", "raw umber", "yellow ochre", "vermilion"]);
    let t2 = f.per_column(move |x| far2(&rn, x));
    let t3 = f.per_column(move |x| far3(&rn, x));
    if o.stage("far", &mut c, &mut rng) {
        // each range a step darker and cooler than the one behind it, its
        // foot lost in a warmer mist (mixed into the range's own paint)
        let glowk = |x: f32| (-((x - GLOW_X) / 300.0).powi(2)).exp();
        let r1 = Mask::from_fn(f, move |x, y| smoothstep(top1(x) - 0.6, top1(x) + 0.6, y) * (1.0 - smoothstep(FOOT1 + 4.0, FOOT1 + 8.0, y)));
        let c1 = move |x: f32, y: f32| {
            let m = mix(hex("#b7a3ad"), hex("#cfb09f"), glowk(x), Mix::Light);
            mix(m, hex("#d8c1ad"), smoothstep(top1(x), FOOT1 + 6.0, y) * 0.8, Mix::Light)
        };
        let hd = st.body().palette(&far_pal).color(c1).angle(|_, _| 0.0).angle_jitter(0.08).length(12.0, 40.0).coverage(3.0).pressure(0.45, 0.7).medium(0.35).clip(true).threshold(0.3);
        c.work(&r1, &hd, 201);
        c.dry();
        let foot2 = HORIZON + 30.0;
        let r2 = Mask::from_fn(f, move |x, y| smoothstep(t2(x) - 0.6, t2(x) + 0.6, y) * (1.0 - smoothstep(foot2 + 6.0, foot2 + 10.0, y)));
        let c2 = move |x: f32, y: f32| {
            let m = mix(hex("#978ea3"), hex("#ad9a9d"), glowk(x), Mix::Light);
            mix(m, hex("#cdb9ab"), smoothstep(t2(x) + 4.0, foot2 + 8.0, y).powf(1.4) * 0.9, Mix::Light)
        };
        let hd = st.body().palette(&far_pal).color(c2).angle(|_, _| 0.0).angle_jitter(0.1).length(12.0, 40.0).coverage(3.0).pressure(0.45, 0.7).medium(0.3).clip(true).threshold(0.3);
        c.work(&r2, &hd, 202);
        if let Some(b) = st.blend() {
            let foot = Mask::from_fn(f, move |x, y| r2.sample(x, y) * smoothstep(t2(x) + 6.0, t2(x) + 14.0, y));
            c.work(&foot, &b.angle(|_, _| 0.0).length(40.0, 120.0), 203);
        }
        c.dry();
        let foot3 = HORIZON + 78.0;
        let r3 = Mask::from_fn(f, move |x, y| smoothstep(t3(x) - 0.6, t3(x) + 0.6, y) * (1.0 - smoothstep(foot3 + 6.0, foot3 + 10.0, y)));
        let c3 = move |x: f32, y: f32| {
            let m = mix(hex("#727a90"), hex("#857f8e"), glowk(x), Mix::Light);
            mix(m, hex("#c4b6ad"), smoothstep(t3(x) + 8.0, foot3 + 8.0, y).powf(1.3) * 0.95, Mix::Light)
        };
        let hd = st.body().palette(&far_pal).color(c3).angle(|_, _| 0.0).angle_jitter(0.12).length(10.0, 36.0).coverage(3.0).pressure(0.5, 0.75).medium(0.25).clip(true).threshold(0.3);
        c.work(&r3, &hd, 204);
        if let Some(b) = st.blend() {
            let foot = Mask::from_fn(f, move |x, y| r3.sample(x, y) * smoothstep(t3(x) + 10.0, t3(x) + 22.0, y));
            c.work(&foot, &b.angle(|_, _| 0.0).length(40.0, 120.0), 205);
        }
        c.dry();
    }

    // ------------------------------------------------ the sea of mist
    let fg = f.per_column(move |x| fg_top(&rn, x));
    let rl = f.per_column(move |x| ridge_l(&rn, x));
    let rr = f.per_column(move |x| ridge_r(&rn, x));
    let mist_col = move |x: f32, y: f32| {
        // lit from the sky above, warmer and lighter toward the glow and at
        // its far edge, cooler and grayer as it comes nearer and lies lower
        let g = (-((x - GLOW_X) / 360.0).powi(2)).exp();
        let near = smoothstep(HORIZON + 40.0, 620.0, y);
        let far = mix(hex("#cbb7aa"), hex("#dcc5ab"), g, Mix::Light);
        let low = mix(hex("#a9a6ae"), hex("#b8aca8"), g, Mix::Light);
        mix(far, low, near, Mix::Light)
    };
    if o.stage("mist", &mut c, &mut rng) {
        let top3 = t3;
        let mist = Mask::from_fn(f, move |x, y| {
            let t = top1(x).max(t2(x)).min(top3(x));
            let _ = t;
            if y > FOOT1 + 2.0 && y < fg(x) + 8.0 && y > top3(x).min(t2(x)) + 1.0 { 1.0 } else { 0.0 }
        });
        // only where the far ranges' paint doesn't already lie
        let mist = mist.mul_fn(move |x, y| {
            let in2 = y > t2(x) && y < HORIZON + 38.0;
            let in3 = y > top3(x) && y < HORIZON + 86.0;
            if in2 || in3 { smoothstep(HORIZON + 30.0, HORIZON + 40.0, y).max(if in3 { smoothstep(HORIZON + 78.0, HORIZON + 88.0, y) } else { 1.0 }) * if in3 { smoothstep(HORIZON + 78.0, HORIZON + 88.0, y) } else { 1.0 } } else { 1.0 }
        });
        let hd = st.broad().palette(&far_pal).color(mist_col).angle(|_, _| 0.0).angle_jitter(0.05).length(50.0, 160.0).coverage(4.0).clip(true).threshold(0.3);
        c.work(&mist, &hd, 301);
        if let Some(b) = st.blend() {
            c.work(&mist, &b.angle(|_, _| 0.0), 302);
        }
        c.dry();
    }

    // the wooded ridges rising out of the mist
    let wood_pal = fam(&greens, &["lead white", "Prussian blue", "cobalt blue", "raw umber", "bone black", "yellow ochre", "green earth", "pale smalt"]);
    if o.stage("ridges", &mut c, &mut rng) {
        for (k, (top, depth, dark)) in [(rl as &(dyn Fn(f32) -> f32 + Sync), 70.0f32, hex("#48505c")), (rr as &(dyn Fn(f32) -> f32 + Sync), 60.0, hex("#3e4652"))].into_iter().enumerate() {
            let region = Mask::from_fn(f, move |x, y| smoothstep(top(x) - 0.5, top(x) + 0.5, y) * (1.0 - smoothstep(top(x) + depth, top(x) + depth + 6.0, y)) * if y < fg(x) + 4.0 { 1.0 } else { 0.0 });
            let col = move |x: f32, y: f32| {
                let d = (y - top(x)) / depth;
                mix(dark, mist_col(x, y), smoothstep(0.25, 0.95, d).powf(0.9), Mix::Light)
            };
            let hd = st.body().palette(&wood_pal).color(col).angle(|_, _| 0.05).angle_jitter(0.15).length(8.0, 26.0).coverage(3.0).pressure(0.5, 0.8).clip(true).threshold(0.3);
            c.work(&region, &hd, 401 + k as u64);
            // the fir tops along the crest: short upright hatching
            let crest = Mask::from_fn(f, move |x, y| smoothstep(top(x) - 0.5, top(x) + 0.5, y) * (1.0 - smoothstep(top(x) + 8.0, top(x) + 14.0, y)));
            let hd = st.hatch().palette(&wood_pal).color(move |_, _| dark).angle(|_, _| PI / 2.0).angle_jitter(0.2).length(2.5, 6.0).coverage(1.5).clip(true).threshold(0.4);
            c.work(&crest, &hd, 411 + k as u64);
            if let Some(b) = st.blend() {
                let foot = Mask::from_fn(f, move |x, y| region.sample(x, y) * smoothstep(0.35, 0.6, (y - top(x)) / depth));
                c.work(&foot, &b.angle(|_, _| 0.0).length(30.0, 100.0), 421 + k as u64);
            }
        }
        c.dry();
    }

    // ------------------------------------------------ the near summit
    // granite boulders on it, lit from the glow behind and the sky above
    let fg_mask = Mask::from_fn(f, move |x, y| smoothstep(fg(x) - 0.6, fg(x) + 0.6, y));
    if o.stage("summit", &mut c, &mut rng) {
        let mut form = Form::new(f);
        let rock = |cx: f32, cy: f32, sx: f32, sy: f32, sz: f32, yaw: f32, seed: u32| {
            let cc = [cx, cy, 0.0];
            Sdf::block(cc, [sx, sy, sz], sy * 0.25)
                .union(Sdf::ellipsoid([cx - sx * 0.15, cy - sy * 0.35, 0.0], [sx * 0.35, sy * 0.3, sz * 0.4]), sy * 0.2)
                .turn(cc, yaw, 0.25, 0.04)
                .rough(sy * 0.05, sy * 0.6, seed, false)
                .cut([cx, cy - sy * 0.42, 0.0], [-0.3, -1.0, 0.25], 10, sy * 0.05)
                .cut([cx + sx * 0.38, cy, 0.0], [1.0, -0.2, 0.3], 11, sy * 0.04)
                .rough(sy * 0.012, sy * 0.15, seed + 1, true)
        };
        let ids = [
            form.add(&rock(150.0, 574.0, 230.0, 70.0, 120.0, 0.25, 1), 0.3),
            form.add(&rock(300.0, 578.0, 90.0, 40.0, 70.0, -0.4, 3), 0.3),
            form.add(&rock(655.0, 515.0, 120.0, 46.0, 80.0, 0.5, 5), 0.3),
            form.add(&rock(930.0, 655.0, 220.0, 110.0, 140.0, -0.3, 7), 0.2),
        ];
        form.light(Light::new((-1.0, -0.45), -0.35).ambient(0.4).penumbra(0.1));
        let rocks = form.silhouette(&ids, |_| 0.5);
        let ground = fg_mask.clone().union(&rocks);
        let form = &form;
        // one dark for ground and the rocks' shadow sides, laid together
        let heath = Fbm::new(21, 4, 60.0);
        let earth = move |x: f32, y: f32| -> Rgb {
            let v = heath.get01(x * 1.2, y * 2.0);
            let a = mix(hex("#2c2b25"), hex("#3a3527"), v, Mix::Pigment);
            // the far edge of the summit takes a little of the sky
            let e = 1.0 - smoothstep(fg(x) + 2.0, fg(x) + 30.0, y);
            mix(a, hex("#57585c"), 0.35 * e, Mix::Pigment)
        };
        let col = move |x: f32, y: f32| -> Rgb {
            match form.sample(x, y) {
                Some(s) => {
                    let v = s.shade.value.clamp(0.0, 1.0);
                    let shadow = hex("#34353a");
                    let lit = mix(hex("#7c7c82"), hex("#9a8d84"), smoothstep(-0.2, 0.6, -s.n[0]), Mix::Pigment);
                    mix(shadow, lit, smoothstep(0.25, 0.8, v) * 0.35, Mix::Pigment)
                }
                None => earth(x, y),
            }
        };
        let hd = st.body().palette(&wood_pal).color(col).angle(move |x, y| if form.sample(x, y).is_some() { form.fall(x, y) } else { -0.12 }).angle_jitter(0.3).length(10.0, 34.0).coverage(3.4).pressure(0.55, 0.85).clip(true).threshold(0.3);
        c.work(&ground, &hd, 501);
        // the rocks' lit planes: the tops and the faces toward the glow
        let lit = form.mask(|s| smoothstep(0.35, 0.7, s.shade.value)).mul(&rocks);
        let lcol = move |x: f32, y: f32| -> Rgb {
            match form.sample(x, y) {
                Some(s) => {
                    let v = s.shade.value.clamp(0.0, 1.0);
                    let lit = mix(hex("#6e7078"), hex("#a2958a"), smoothstep(-0.2, 0.7, -s.n[0]), Mix::Pigment);
                    mix(hex("#4a4b50"), lit, smoothstep(0.35, 0.9, v), Mix::Pigment)
                }
                None => hex("#4a4b50"),
            }
        };
        let hd = st.body().palette(&wood_pal).color(lcol).angle(move |x, y| form.across(x, y)).angle_jitter(0.2).length(6.0, 20.0).coverage(2.2).pressure(0.5, 0.8).clip(true).threshold(0.3);
        c.work(&lit, &hd, 502);
        c.dry();
    }

    // ------------------------------------------------ the spruces
    if o.stage("spruces", &mut c, &mut rng) {
        let dark = hex("#1d231f");
        let lit = hex("#4a5552");
        for (i, &(x, h, lean)) in [(772.0f32, 318.0f32, -0.01f32), (836.0, 214.0, 0.015), (893.0, 262.0, 0.0), (712.0, 120.0, 0.02), (965.0, 150.0, -0.02)].iter().enumerate() {
            let base = fg_top(&rn, x) + 14.0;
            spruce(&mut c, &st, &wood_pal, x, base, h, lean, dark, lit, 600 + 10 * i as u64);
        }
        c.dry();
    }

    // ------------------------------------------------ heath and grass
    if o.stage("heath", &mut c, &mut rng) {
        let mut rg = paint::Rng::new(77);
        let clump = Fbm::new(31, 3, 45.0);
        let tool = Tool { point: 1.0, ..Tool::round_sable(0.9) };
        let mut held = Held::new(tool, 78);
        let pale = wood_pal.paint(hex("#6f6a58"), 0.15);
        let deep = wood_pal.paint(hex("#26261f"), 0.15);
        let mut n = 0;
        for _ in 0..9000 {
            let x = rg.range(0.0, 1000.0);
            let y = rg.range(fg_top(&rn, x) + 4.0, H + 5.0);
            // clumps, larger nearer
            if clump.get01(x, y * 1.5) < 0.58 {
                continue;
            }
            let near = smoothstep(fg_top(&rn, x), H, y);
            let len = (3.0 + 9.0 * near) * rg.range(0.6, 1.4);
            let lean = rg.normal() * 0.25 + 0.1;
            let p = if rg.next_f32() < 0.35 { pale } else { deep };
            held.reload(p, 0.5);
            let pts = vec![(x, y), (x + lean * len * 0.4, y - len * 0.5), (x + lean * len, y - len)];
            c.drag(&mut held, &Gesture::new(pts).pressure(0.6, 0.05).ramps(0.05, 0.6), None);
            n += 1;
        }
        eprintln!("grass: {n} blades");
        c.dry();
    }

    o.finish(&mut c, &mut rng, &Finish::aged(st.relief));
}

