spr=r'''// ckpt: from spruces
/// A spruce written with the brush, as boughs: a dark core (trunk and the
/// inner boughs, short strokes), then each bough pulled from the trunk out
/// and down with its tip turned up, the twigs hanging from it like a
/// curtain, a few touches of sky light on the tops of the boughs toward
/// the glow, and the leader. Tiers at uneven spacing, some boughs missing,
/// so the sky shows through.
#[allow(clippy::too_many_arguments)]
fn spruce(c: &mut paint::Canvas, st: &Style, pal: &Palette, x0: f32, base: f32, hgt: f32, lean: f32, dark: Rgb, lit: Rgb, seed: u64) {
    let f = c.frame();
    let mut rng = paint::Rng::new(seed);
    let cx = move |v: f32| x0 + lean * hgt * v + 1.2 * (v * 9.0 + seed as f32).sin();
    let wmax = 0.165 * hgt;
    let width = move |v: f32| wmax * (1.0 - v).max(0.0).powf(0.95) * (0.8 + 0.2 * smoothstep(0.0, 0.15, v));
    // 1. the core: trunk and inner boughs, dark, a ragged column
    let core = Mask::from_fn(f, move |x, y| {
        let v = (base - y) / hgt;
        if !(0.0..=0.97).contains(&v) {
            return 0.0;
        }
        let w = 0.38 * width(v) + 0.8;
        smoothstep(w + 0.5, w - 0.5, (x - cx(v)).abs())
    })
    .roughen(seed as u32, 4.0, 1.5, 0.5);
    let hd = st
        .hatch()
        .palette(pal)
        .color(move |_, _| dark)
        .angle(move |x, y| {
            let v = ((base - y) / hgt).clamp(0.0, 1.0);
            if x > cx(v) { 0.6 } else { PI - 0.6 }
        })
        .angle_jitter(0.3)
        .length(3.0, 7.0)
        .coverage(3.0)
        .clip(true)
        .threshold(0.3);
    c.work(&core, &hd, seed + 1);
    // 2. the boughs, bottom up (the upper ones lie over the lower)
    let dark_p = pal.paint(dark, 0.12);
    let twig_p = pal.paint(mix(dark, lit, 0.08, Mix::Pigment), 0.15);
    let lit_p = pal.paint(lit, 0.18);
    let mut bh = Held::new(Tool { point: 0.7, ..Tool::round_sable(2.0) }, seed + 2);
    let mut th = Held::new(Tool { point: 1.0, ..Tool::round_sable(1.1) }, seed + 3);
    let mut lh = Held::new(Tool { point: 0.9, ..Tool::round_sable(1.0) }, seed + 4);
    bh.load(dark_p, 0.8);
    th.load(twig_p, 0.7);
    lh.load(lit_p, 0.6);
    let mut v = 0.03 + 0.02 * rng.range(0.0, 1.0);
    while v < 0.94 {
        let step = (10.0 / hgt) * rng.range(0.6, 1.5) * (1.0 - 0.45 * v);
        let yb = base - v * hgt;
        for side in [-1.0f32, 1.0] {
            // now and then a bough is missing, or short (the sky shows through)
            let r = rng.range(0.0, 1.0);
            if r < 0.1 {
                continue;
            }
            let len = width(v) * if r < 0.25 { rng.range(0.35, 0.6) } else { rng.range(0.8, 1.2) };
            if len < 1.2 {
                continue;
            }
            let droop = len * rng.range(0.18, 0.45);
            let up = droop * rng.range(0.1, 0.35);
            let xs = cx(v);
            let bough: Vec<(f32, f32)> = (0..7)
                .map(|i| {
                    let t = i as f32 / 6.0;
                    let x = xs + side * len * t;
                    let y = yb + droop * t.powf(1.6) - up * smoothstep(0.7, 1.0, t) + rng.normal() * 0.25;
                    (x, y)
                })
                .collect();
            if bh.fullness() < 0.4 {
                bh.reload(dark_p, 0.8);
            }
            let wp = (0.35 + 0.5 * (len / wmax).min(1.0)).min(0.9);
            c.drag(&mut bh, &Gesture::new(bough.clone()).pressure(wp, 0.15).ramps(0.02, 0.35), None);
            // the twigs hanging from it
            let nt = (len / 1.4) as usize + 1;
            for _ in 0..nt {
                let t: f32 = rng.range(0.15, 1.0);
                let i = ((t * 6.0) as usize).min(5);
                let ft = t * 6.0 - i as f32;
                let (px, py) = (bough[i].0 + (bough[i + 1].0 - bough[i].0) * ft, bough[i].1 + (bough[i + 1].1 - bough[i].1) * ft);
                let hang = (1.5 + 3.5 * rng.range(0.0, 1.0)) * (0.5 + 0.5 * (len / wmax).min(1.0)) * (1.0 - 0.3 * t);
                let a = PI / 2.0 - side * rng.range(0.1, 0.5);
                let tip = (px + a.cos() * hang, py + a.sin() * hang);
                let mid = (px + a.cos() * hang * 0.5 + side * 0.3, py + a.sin() * hang * 0.5);
                if th.fullness() < 0.35 {
                    th.reload(twig_p, 0.7);
                }
                c.drag(&mut th, &Gesture::new(vec![(px, py - 0.3), mid, tip]).pressure(0.55, 0.05).ramps(0.05, 0.5), None);
            }
            // sky light on the bough's top, mostly on the side toward the glow
            if (side < 0.0 && rng.range(0.0, 1.0) < 0.75) || rng.range(0.0, 1.0) < 0.15 {
                let t0 = rng.range(0.35, 0.6);
                let t1 = (t0 + rng.range(0.2, 0.4)).min(0.98);
                let pts: Vec<(f32, f32)> = (0..4)
                    .map(|i| {
                        let t = t0 + (t1 - t0) * i as f32 / 3.0;
                        let x = xs + side * len * t;
                        (x, yb + droop * t.powf(1.6) - up * smoothstep(0.7, 1.0, t) - 0.9)
                    })
                    .collect();
                if lh.fullness() < 0.3 {
                    lh.reload(lit_p, 0.6);
                }
                c.drag(&mut lh, &Gesture::new(pts).pressure(0.45, 0.1).ramps(0.1, 0.5), None);
            }
        }
        v += step;
    }
    // 3. the leader, a little crooked, with a tuft or two
    let mut rh = Held::new(Tool { point: 1.0, ..Tool::rigger(0.8) }, seed + 5);
    rh.load(dark_p, 0.7);
    let top = base - hgt;
    let pts = vec![(cx(0.88), base - 0.88 * hgt), (cx(0.95) + 0.4, base - 0.95 * hgt), (cx(1.0) - 0.3, top - 1.0)];
    c.drag(&mut rh, &Gesture::new(pts).pressure(0.8, 0.05).ramps(0.05, 0.5), None);
    for k in 0..3 {
        let v = 0.9 + 0.025 * k as f32;
        let y = base - v * hgt;
        for side in [-1.0f32, 1.0] {
            let l = 2.0 + rng.range(0.0, 2.0);
            c.drag(&mut th, &Gesture::new(vec![(cx(v), y), (cx(v) + side * l, y + l * 0.5)]).pressure(0.45, 0.05).ramps(0.05, 0.5), None);
        }
    }
}
// ckpt: end

